CREATE TABLE public.organizations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL CHECK(length(trim(name)) BETWEEN 1 AND 150),logo_url text,created_at timestamptz NOT NULL DEFAULT now()); GRANT SELECT,UPDATE ON public.organizations TO authenticated; GRANT ALL ON public.organizations TO service_role; ALTER TABLE public.organizations ENABLE ROW LEVEL SECURITY;
INSERT INTO public.organizations(id,name,logo_url) SELECT '11111111-1111-4111-8111-111111111111','Smiley''s Tinting Plus',(SELECT logo_url FROM public.company_settings LIMIT 1);
CREATE FUNCTION public.current_org_id() RETURNS uuid LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE result uuid; BEGIN SELECT org_id INTO result FROM public.profiles WHERE user_id=auth.uid() LIMIT 1; RETURN result; END $$; REVOKE ALL ON FUNCTION public.current_org_id() FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.current_org_id() TO authenticated,service_role;
DO $$ DECLARE tbl text; BEGIN FOREACH tbl IN ARRAY ARRAY['profiles','employee_records','user_roles','user_workspace_access','user_pins','notification_settings','company_settings','applicants','applicant_documents','clock_punches','client_sites','client_portal_access','client_invoices','invoice_line_items','contractors','contractor_payments','creditors','employee_additions','employee_deductions','employee_bank_info','employee_documents','payslips','employee_payslips','payroll_runs','projects','project_assignments','project_time_logs','crews','crew_members','equipment','equipment_checkouts','daily_reports','emergency_alerts','geofence_zones','guard_assignments','guard_licenses','incident_reports','late_clock_in_alerts','leave_balances','leave_requests','patrol_logs','post_order_signoffs','qbo_account_mappings','qbo_chart_of_accounts','qbo_connection','qbo_employee_map','qbo_sync_log','training_documents','simulated_attendance_punches'] LOOP EXECUTE format('ALTER TABLE public.%I ADD COLUMN org_id uuid REFERENCES public.organizations(id) DEFAULT public.current_org_id()',tbl); IF tbl IN ('profiles','employee_records') THEN EXECUTE format('ALTER TABLE public.%I DISABLE TRIGGER validate_employee_folder',tbl); END IF; EXECUTE format('UPDATE public.%I SET org_id=''11111111-1111-4111-8111-111111111111'' WHERE org_id IS NULL',tbl); IF tbl IN ('profiles','employee_records') THEN EXECUTE format('ALTER TABLE public.%I ENABLE TRIGGER validate_employee_folder',tbl); END IF; EXECUTE format('CREATE INDEX %I ON public.%I(org_id)',tbl||'_org_idx',tbl); EXECUTE format('CREATE POLICY company_isolation ON public.%I AS RESTRICTIVE FOR ALL TO authenticated USING (org_id=public.current_org_id()) WITH CHECK (org_id=public.current_org_id())',tbl); END LOOP; END $$;
CREATE OR REPLACE VIEW public.payroll_employee_directory WITH(security_invoker=true) AS SELECT id,user_id,first_name,last_name,email,phone,department,job_title,nic_number,tan_number,person_id,start_date,schedule,std_hours_per_day,ot_rate,monthly_salary,status,created_at,updated_at,jurisdiction,social_security_number,tax_id_number,hr_details,deleted_at,true AS account_linked,org_id FROM public.profiles UNION ALL SELECT id,user_id,first_name,last_name,email,phone,department,job_title,nic_number,tan_number,person_id,start_date,schedule,std_hours_per_day,ot_rate,monthly_salary,status,created_at,updated_at,jurisdiction,social_security_number,tax_id_number,hr_details,deleted_at,false AS account_linked,org_id FROM public.employee_records;
CREATE OR REPLACE VIEW public.payroll_payslip_directory WITH(security_invoker=true) AS SELECT id,payroll_run_id,user_id,period,gross_pay,basic_pay,overtime_pay,employee_nic,employer_nic,paye,total_deductions,net_pay,created_at,department_snapshot,employee_name_snapshot,currency_code,org_id FROM public.payslips UNION ALL SELECT id,payroll_run_id,user_id,period,gross_pay,basic_pay,overtime_pay,employee_nic,employer_nic,paye,total_deductions,net_pay,created_at,department_snapshot,employee_name_snapshot,currency_code,org_id FROM public.employee_payslips;
CREATE POLICY own_company ON public.organizations FOR SELECT TO authenticated USING(id=public.current_org_id()); CREATE POLICY manage_own_company ON public.organizations FOR UPDATE TO authenticated USING(id=public.current_org_id() AND public.has_role(auth.uid(),'admin')) WITH CHECK(id=public.current_org_id() AND public.has_role(auth.uid(),'admin'));
CREATE FUNCTION public.employee_org_id(_employee uuid) RETURNS uuid LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT org_id FROM public.profiles WHERE user_id=_employee UNION ALL SELECT org_id FROM public.employee_records WHERE user_id=_employee LIMIT 1 $$; REVOKE ALL ON FUNCTION public.employee_org_id(uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.employee_org_id(uuid) TO authenticated,service_role;
CREATE FUNCTION public.enforce_company_record() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE j jsonb:=to_jsonb(NEW); related uuid; ref record; employee_field text; caller_org uuid:=public.current_org_id(); BEGIN IF TG_OP='UPDATE' AND NEW.org_id IS DISTINCT FROM OLD.org_id THEN RAISE EXCEPTION 'Company assignment cannot be changed'; END IF; IF TG_TABLE_NAME NOT IN ('profiles','employee_records') THEN employee_field:=CASE WHEN j ? 'employee_key' THEN 'employee_key' WHEN j ? 'submitted_by' THEN 'submitted_by' WHEN j ? 'user_id' THEN 'user_id' ELSE NULL END; IF employee_field IS NOT NULL AND j->>employee_field IS NOT NULL THEN related:=public.employee_org_id((j->>employee_field)::uuid); IF related IS NULL AND TG_TABLE_NAME NOT IN ('user_roles','notification_settings') THEN RAISE EXCEPTION 'Employee company is required'; END IF; IF NEW.org_id IS NULL THEN NEW.org_id:=related; ELSIF NEW.org_id IS DISTINCT FROM related THEN RAISE EXCEPTION 'Employee belongs to another company'; END IF; END IF; END IF; IF NEW.org_id IS NULL THEN NEW.org_id:=caller_org; END IF; IF NEW.org_id IS NULL AND TG_TABLE_NAME NOT IN ('profiles','user_roles','notification_settings') THEN RAISE EXCEPTION 'Company membership required'; END IF; IF auth.uid() IS NOT NULL AND coalesce(auth.role(),'')<>'service_role' AND NEW.org_id IS DISTINCT FROM caller_org THEN RAISE EXCEPTION 'Company access denied'; END IF; FOR ref IN SELECT * FROM (VALUES('site_id','client_sites'),('project_id','projects'),('crew_id','crews'),('equipment_id','equipment'),('creditor_id','creditors'),('payroll_run_id','payroll_runs'),('invoice_id','client_invoices'),('applicant_id','applicants'),('geofence_zone_id','geofence_zones')) v(key,t) LOOP IF j->>ref.key IS NOT NULL THEN EXECUTE format('SELECT org_id FROM public.%I WHERE id=$1',ref.t) INTO related USING (j->>ref.key)::uuid; IF related IS NULL OR related IS DISTINCT FROM NEW.org_id THEN RAISE EXCEPTION 'Related record belongs to another company'; END IF; END IF; END LOOP; RETURN NEW; END $$;
DO $$ DECLARE tbl record; BEGIN FOR tbl IN SELECT c.table_name FROM information_schema.columns c JOIN information_schema.tables it USING(table_schema,table_name) WHERE c.table_schema='public' AND c.column_name='org_id' AND it.table_type='BASE TABLE' LOOP EXECUTE format('CREATE TRIGGER enforce_company_record BEFORE INSERT OR UPDATE ON public.%I FOR EACH ROW EXECUTE FUNCTION public.enforce_company_record()',tbl.table_name); END LOOP; END $$;
CREATE OR REPLACE FUNCTION public.has_role(_user_id uuid,_role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles r JOIN public.profiles p ON p.user_id=r.user_id WHERE r.user_id=_user_id AND r.role=_role AND r.org_id=p.org_id AND p.org_id IS NOT NULL) $$; CREATE OR REPLACE FUNCTION public.is_admin_or_manager(_user_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.has_role(_user_id,'admin') OR public.has_role(_user_id,'manager') $$; CREATE OR REPLACE FUNCTION public.is_staff(_user_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles r JOIN public.profiles p ON p.user_id=r.user_id WHERE r.user_id=_user_id AND r.org_id=p.org_id AND p.org_id IS NOT NULL) $$;
CREATE OR REPLACE FUNCTION public.can_access_employee_document(_employee uuid,_shared boolean) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.employee_org_id(_employee)=public.current_org_id() AND ((public.is_admin_or_manager(auth.uid()) AND public.has_workspace_access(auth.uid(),'hr')) OR (_shared AND _employee=auth.uid())) $$;
CREATE OR REPLACE FUNCTION public.has_workspace_access(_user_id uuid,_module text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.is_staff(_user_id) AND EXISTS(SELECT 1 FROM public.user_roles r WHERE r.user_id=_user_id AND (r.role='admin' OR (_module IN ('hr','payroll','reports','attendance','leave','recruitment','field','security','billing','training','quickbooks','settings') AND (r.role='manager' OR _module IN ('attendance','field','security','training')) AND CASE WHEN EXISTS(SELECT 1 FROM public.user_workspace_access a WHERE a.user_id=_user_id) THEN EXISTS(SELECT 1 FROM public.user_workspace_access a WHERE a.user_id=_user_id AND _module=ANY(a.modules)) ELSE true END))) $$;
CREATE POLICY employee_profile_scope ON public.profiles AS RESTRICTIVE FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.is_admin_or_manager(auth.uid())); CREATE POLICY employee_clock_scope ON public.clock_punches AS RESTRICTIVE FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.is_admin_or_manager(auth.uid()));
CREATE TABLE public.system_settings(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),org_id uuid NOT NULL REFERENCES public.organizations(id) DEFAULT public.current_org_id(),nic_rate numeric NOT NULL DEFAULT 0.05 CHECK(nic_rate BETWEEN 0 AND 1),paye_rate numeric NOT NULL DEFAULT 0.30 CHECK(paye_rate BETWEEN 0 AND 1),paye_threshold numeric NOT NULL DEFAULT 1500 CHECK(paye_threshold>=0),geofence_radius integer NOT NULL DEFAULT 200 CHECK(geofence_radius BETWEEN 10 AND 10000),test_only boolean NOT NULL DEFAULT true CHECK(test_only),UNIQUE(org_id)); GRANT SELECT,INSERT,UPDATE ON public.system_settings TO authenticated; GRANT ALL ON public.system_settings TO service_role; ALTER TABLE public.system_settings ENABLE ROW LEVEL SECURITY; CREATE POLICY company_test_settings ON public.system_settings FOR ALL TO authenticated USING(org_id=public.current_org_id() AND public.is_admin_or_manager(auth.uid())) WITH CHECK(org_id=public.current_org_id() AND public.has_role(auth.uid(),'admin'));
CREATE TABLE public.audit_logs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),org_id uuid NOT NULL REFERENCES public.organizations(id) DEFAULT public.current_org_id(),employee_id uuid,action text NOT NULL,details jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now()); GRANT SELECT ON public.audit_logs TO authenticated; GRANT ALL ON public.audit_logs TO service_role; ALTER TABLE public.audit_logs ENABLE ROW LEVEL SECURITY; CREATE POLICY own_company_audit ON public.audit_logs FOR SELECT TO authenticated USING(org_id=public.current_org_id() AND public.has_role(auth.uid(),'admin'));
CREATE TABLE public.prototype_employees(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),org_id uuid NOT NULL REFERENCES public.organizations(id) DEFAULT public.current_org_id(),name text NOT NULL,job_title text NOT NULL,department text NOT NULL,pay_frequency text NOT NULL CHECK(pay_frequency IN ('Monthly','Hourly')),pay_rate numeric NOT NULL CHECK(pay_rate>=0),weekly_hours numeric NOT NULL CHECK(weekly_hours BETWEEN 0 AND 168),creditor_name text,original_loan numeric NOT NULL DEFAULT 0,loan_balance numeric NOT NULL DEFAULT 0,monthly_deduction numeric NOT NULL DEFAULT 0,UNIQUE(org_id,name)); GRANT SELECT ON public.prototype_employees TO authenticated; GRANT ALL ON public.prototype_employees TO service_role; ALTER TABLE public.prototype_employees ENABLE ROW LEVEL SECURITY; CREATE POLICY prototype_company ON public.prototype_employees FOR SELECT TO authenticated USING(org_id=public.current_org_id() AND public.is_admin_or_manager(auth.uid()));
CREATE TABLE public.organization_simulation_clock(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),org_id uuid NOT NULL UNIQUE REFERENCES public.organizations(id) DEFAULT public.current_org_id(),run_id uuid NOT NULL DEFAULT gen_random_uuid(),simulated_start timestamptz NOT NULL,real_start timestamptz NOT NULL DEFAULT now(),enabled boolean NOT NULL DEFAULT false,changed_by uuid); GRANT SELECT ON public.organization_simulation_clock TO authenticated; GRANT ALL ON public.organization_simulation_clock TO service_role; ALTER TABLE public.organization_simulation_clock ENABLE ROW LEVEL SECURITY; CREATE POLICY company_simulation ON public.organization_simulation_clock FOR SELECT TO authenticated USING(org_id=public.current_org_id() AND public.has_workspace_access(auth.uid(),'attendance'));
INSERT INTO public.organization_simulation_clock(org_id,run_id,simulated_start,real_start,enabled,changed_by) SELECT '11111111-1111-4111-8111-111111111111',run_id,simulated_start,real_start,enabled,changed_by FROM public.attendance_simulation_clock; COMMENT ON TABLE public.attendance_simulation_clock IS 'DEPRECATED: replaced by organization_simulation_clock for company-isolated clocks';
CREATE FUNCTION public.reset_company_simulation(_start timestamptz,_enabled boolean) RETURNS public.organization_simulation_clock LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE result public.organization_simulation_clock; BEGIN IF NOT public.is_admin_or_manager(auth.uid()) OR NOT public.has_workspace_access(auth.uid(),'attendance') OR public.current_org_id() IS NULL THEN RAISE EXCEPTION 'Attendance management access required'; END IF; IF _enabled IS NULL OR _start IS NULL OR NOT isfinite(_start) OR _start<'2000-01-01' OR _start>='2101-01-01' THEN RAISE EXCEPTION 'Choose a date between 2000 and 2100'; END IF; INSERT INTO public.organization_simulation_clock(org_id,simulated_start,real_start,enabled,changed_by) VALUES(public.current_org_id(),_start,clock_timestamp(),_enabled,auth.uid()) ON CONFLICT(org_id) DO UPDATE SET simulated_start=excluded.simulated_start,real_start=excluded.real_start,enabled=excluded.enabled,changed_by=excluded.changed_by,run_id=gen_random_uuid() RETURNING * INTO result; RETURN result; END $$; REVOKE ALL ON FUNCTION public.reset_company_simulation(timestamptz,boolean) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.reset_company_simulation(timestamptz,boolean) TO authenticated;
CREATE OR REPLACE FUNCTION public.record_simulated_punch(_type text) RETURNS public.simulated_attendance_punches LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE settings public.organization_simulation_clock; previous text; result public.simulated_attendance_punches; BEGIN IF auth.uid() IS NULL OR NOT public.has_workspace_access(auth.uid(),'attendance') THEN RAISE EXCEPTION 'Attendance workspace access required'; END IF; IF _type IS NULL OR _type NOT IN ('clock_in','clock_out') THEN RAISE EXCEPTION 'Invalid punch type'; END IF; SELECT * INTO settings FROM public.organization_simulation_clock WHERE org_id=public.current_org_id() FOR UPDATE; IF NOT FOUND OR NOT settings.enabled THEN RAISE EXCEPTION 'Simulation is not active'; END IF; SELECT punch_type INTO previous FROM public.simulated_attendance_punches WHERE user_id=auth.uid() AND org_id=public.current_org_id() AND run_id=settings.run_id ORDER BY recorded_at DESC LIMIT 1; IF (_type='clock_in' AND previous='clock_in') OR (_type='clock_out' AND previous IS DISTINCT FROM 'clock_in') THEN RAISE EXCEPTION 'Clock in and clock out must alternate'; END IF; INSERT INTO public.simulated_attendance_punches(user_id,run_id,punch_type,simulated_at,org_id) VALUES(auth.uid(),settings.run_id,_type,settings.simulated_start+(clock_timestamp()-settings.real_start),settings.org_id) RETURNING * INTO result; RETURN result; END $$; REVOKE EXECUTE ON FUNCTION public.reset_attendance_simulation(timestamptz,boolean) FROM authenticated,anon,PUBLIC;
DO $$ DECLARE f record; d text; BEGIN FOR f IN SELECT oid,proname FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname IN ('approve_payroll_run','approve_department_payroll') LOOP d:=pg_get_functiondef(f.oid); d:=replace(d,'WHERE user_id=(row->>''user_id'')::uuid','WHERE org_id=public.current_org_id() AND user_id=(row->>''user_id'')::uuid'); d:=replace(d,'WHERE deleted_at IS NULL AND lower(status)','WHERE org_id=public.current_org_id() AND deleted_at IS NULL AND lower(status)'); EXECUTE d; END LOOP; SELECT oid INTO f FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname='set_user_workspace_access'; d:=pg_get_functiondef(f.oid); d:=replace(d,'IF _role IS NULL','IF public.employee_org_id(_user_id) IS DISTINCT FROM public.current_org_id() THEN RAISE EXCEPTION ''User belongs to another company''; END IF; IF _role IS NULL'); EXECUTE d; END $$;
CREATE POLICY company_storage_gate ON storage.objects AS RESTRICTIVE FOR ALL TO authenticated USING(CASE WHEN bucket_id='employee-hr-docs' THEN public.employee_org_id((split_part(name,'/',1))::uuid)=public.current_org_id() WHEN bucket_id IN ('field-photos','incident-audio') THEN CASE WHEN split_part(name,'/',2) ~ '^[0-9a-f-]{36}$' THEN public.employee_org_id((split_part(name,'/',2))::uuid)=public.current_org_id() ELSE public.current_org_id()='11111111-1111-4111-8111-111111111111'::uuid END WHEN bucket_id='training-docs' THEN EXISTS(SELECT 1 FROM public.training_documents d WHERE d.file_name=name AND d.org_id=public.current_org_id()) WHEN bucket_id='company-assets' THEN split_part(name,'/',1)=public.current_org_id()::text OR (public.current_org_id()='11111111-1111-4111-8111-111111111111'::uuid AND name NOT LIKE '%/%') ELSE true END) WITH CHECK(CASE WHEN bucket_id='employee-hr-docs' THEN public.employee_org_id((split_part(name,'/',1))::uuid)=public.current_org_id() WHEN bucket_id IN ('field-photos','incident-audio') THEN CASE WHEN split_part(name,'/',2) ~ '^[0-9a-f-]{36}$' THEN public.employee_org_id((split_part(name,'/',2))::uuid)=public.current_org_id() ELSE false END WHEN bucket_id IN ('training-docs','company-assets') THEN split_part(name,'/',1)=public.current_org_id()::text ELSE true END);